function bumpsToRise(nums: number[]): number {
  let prev = nums[0], ops = 0;
  for (let i = 1; i < nums.length; i++) {
    const v = nums[i];
    if (v > prev) prev = v;
    else { ops += prev + 1 - v; prev++; }
  }
  return ops;
}

